   326  /* If 'b' is shorter than 'length' bytes, pads its tail out with zeros to that
   327   * length. */
   328  void
   329  ofpbuf_padto(struct ofpbuf *b, size_t length)
   330  {
   331      if (b->size < length) {
   332          ofpbuf_put_zeros(b, length - b->size);
   333      }
   334  }
